// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(0));
        vm.assume(player != address(this));
        c.AdjustBetAmounts(100);
        bool result = c.hasPlayerWagered(player);
        assertTrue(result == false, "hasPlayerWagered should return false");
    }
}

